223	func instanceHealth(t *testing.T, r *Registry, service, id string) InstanceView {
224		t.Helper()
225		for _, view := range r.Snapshot() {
226			if view.Service != service {
227				continue
228			}
229			for _, inst := range view.Instances {
230				if inst.ID == id {
231					return inst
232				}
233			}
234			t.Fatalf("instance %q not found in service %q", id, service)
235		}
236		t.Fatalf("service %q not found", service)
237		return InstanceView{}
238	}
