646		// is chosen rather than restarting at the smallest id.
647		markHealth(t, r, "svc", "a", 1, 4, true, "")
648		markHealth(t, r, "svc", "b", 1, 5, true, "")
649		if out := selected(t, r, "svc", 1); out.InstanceID != "b" {
