671	
672		// Healthy set is a, c, d. Rotation continues just after the (now removed)
673		// b, so c is chosen, not a.
674		if out := selected(t, r, "svc", 2); out.InstanceID != "c" {
675			t.Fatalf("continue after removed cursor: %+v", out)
