773	// TestSharedRevisionGateEmptyInstanceService locks the rule shared by health
774	// and select: a registered service whose instance list is empty still compares
775	// by its real revision instead of being treated as absent.
776	func TestSharedRevisionGateEmptyInstanceService(t *testing.T) {
777		r := NewRegistry()
778		registerService(t, r, "svc", 0, []Instance{{ID: "a", Address: "h:1"}})
779		registerService(t, r, "svc", 1, nil) // empty list bumps to revision 2
780	
781		// Both operations, wrong expected revision against the empty service: a
782		// conflict carrying the real revision, not not_found at revision 0.
783		upd, _ := r.ValidateHealth("svc", "a", 1, 1, true, "")
784		if out := r.ApplyHealth(upd); out.OK || out.Kind != OutcomeConflict ||
785			out.Expected != 1 || out.Actual != 2 || out.Revision != 2 {
786			t.Fatalf("health empty-service conflict: %+v", out)
787		}
788		sel, _ := r.ValidateSelection("svc", 1)
789		if out := r.Select(sel); out.OK || out.Kind != OutcomeConflict ||
790			out.Expected != 1 || out.Actual != 2 || out.Revision != 2 {
791			t.Fatalf("select empty-service conflict: %+v", out)
792		}
793	
794		// Matching revision: the gate passes. Health then reports the missing
795		// instance (its own not_found), while select reports no_healthy; the two
796		// business results must not be mixed.
797		upd, _ = r.ValidateHealth("svc", "a", 2, 1, true, "")
798		if out := r.ApplyHealth(upd); out.OK || out.Kind != OutcomeNotFound || out.Revision != 2 {
799			t.Fatalf("health through gate on empty service: %+v", out)
800		}
801		sel, _ = r.ValidateSelection("svc", 2)
802		if out := r.Select(sel); out.OK || out.Kind != OutcomeNoHealthy ||
803			out.Revision != 2 || out.InstanceID != "" || out.Address != "" {
804			t.Fatalf("select through gate on empty service: %+v", out)
805		}
806	}
807	
808	// TestSharedRevisionGateConflictPrecedesHealthBusinessRules locks that a
809	// revision mismatch on a health request is reported as conflict even when the
810	// instance is missing or the carried sequence is larger than anything seen.
811	func TestSharedRevisionGateConflictPrecedesHealthBusinessRules(t *testing.T) {
812		r := NewRegistry()
813		registerService(t, r, "svc", 0, []Instance{{ID: "a", Address: "h:1"}})
814		markHealth(t, r, "svc", "a", 1, 5, true, "")
815	
816		// Missing instance plus a larger sequence, wrong revision: conflict first.
817		upd, _ := r.ValidateHealth("svc", "ghost", 9, 100, true, "")
818		out := r.ApplyHealth(upd)
819		if out.OK || out.Kind != OutcomeConflict || out.Expected != 9 ||
820			out.Actual != 1 || out.Revision != 1 {
821			t.Fatalf("missing instance must not mask revision conflict: %+v", out)
822		}
823	
824		// Existing instance with a larger sequence, wrong revision: still conflict;
825		// the observation must not have been written.
826		upd, _ = r.ValidateHealth("svc", "a", 2, 100, false, "down")
827		out = r.ApplyHealth(upd)
828		if out.OK || out.Kind != OutcomeConflict || out.Expected != 2 || out.Actual != 1 {
829			t.Fatalf("larger sequence must not mask revision conflict: %+v", out)
830		}
831		if inst := instanceHealth(t, r, "svc", "a"); inst.Health != HealthHealthy || inst.Sequence != 5 {
832			t.Fatalf("observation written despite conflict: %+v", inst)
833		}
834	
835		// Unknown service with a non-zero expected revision conflicts even though
836		// the instance cannot exist; expected 0 on the same unknown service is the
837		// operation-specific not_found.
838		upd, _ = r.ValidateHealth("other", "a", 3, 100, true, "")
839		if out := r.ApplyHealth(upd); out.OK || out.Kind != OutcomeConflict ||
840			out.Expected != 3 || out.Actual != 0 || out.Revision != 0 {
841			t.Fatalf("unknown service wrong revision: %+v", out)
842		}
843		upd, _ = r.ValidateHealth("other", "a", 0, 1, true, "")
844		if out := r.ApplyHealth(upd); out.OK || out.Kind != OutcomeNotFound || out.Revision != 0 {
845			t.Fatalf("unknown service expected 0: %+v", out)
846		}
847	}
848	
849	// TestSharedRevisionGateValidationPrecedesRevision locks the ordering shared by
850	// both operations: own-field validity is judged before the revision comparison
851	// even when the service is absent, so the answer is invalid rather than
852	// conflict or not_found.
853	func TestSharedRevisionGateValidationPrecedesRevision(t *testing.T) {
854		r := NewRegistry()
855	
856		if _, err := r.ValidateHealth("   ", "a", 5, 1, true, ""); err == nil {
857			t.Fatalf("blank service health should be invalid before the revision check")
858		}
859		if _, err := r.ValidateHealth("missing", "a", -1, 1, true, ""); err == nil {
860			t.Fatalf("negative revision health should be invalid")
861		}
862		if _, err := r.ValidateSelection("   ", 5); err == nil {
863			t.Fatalf("blank service select should be invalid before the revision check")
864		}
865		if _, err := r.ValidateSelection("missing", -1); err == nil {
866			t.Fatalf("negative revision select should be invalid")
867		}
868	}
869	
870	// assertAcceptedServiceState locks the state established before the rejected
871	// replacements: revision 1, original addresses, accepted healthy observations.
872	func assertAcceptedServiceState(t *testing.T, r *Registry) {
873		t.Helper()
874		if rev := r.RevisionOf("svc"); rev != 1 {
875			t.Fatalf("revision should stay 1 after the rejected replacement, got %d", rev)
876		}
877		views := r.Snapshot()
878		if len(views) != 1 || views[0].Service != "svc" || views[0].Revision != 1 {
879			t.Fatalf("service view mutated: %+v", views)
880		}
881		if inst := instanceHealth(t, r, "svc", "a"); inst.Address != "h1:1" ||
882			inst.Health != HealthHealthy || inst.Sequence != 11 || inst.Reason != "" {
883			t.Fatalf("a must keep its original address and accepted healthy record: %+v", inst)
884		}
885		if inst := instanceHealth(t, r, "svc", "b"); inst.Address != "h2:2" ||
886			inst.Health != HealthHealthy || inst.Sequence != 22 || inst.Reason != "" {
887			t.Fatalf("b must keep its original address and accepted healthy record: %+v", inst)
888		}
889	}
890	
891	// TestRegistryInvalidReplacementKeepsAcceptedStateAndCursor covers the invalid
892	// rejection condition: a list whose prefix is valid (and changes an existing
893	// instance's address) but whose later instance has an invalid address is
894	// rejected as a whole. Field validation precedes the revision comparison, so a
895	// simultaneously wrong expectedRevision still reports invalid and Apply is
896	// never reached; neither the valid prefix nor any reset to unknown may leak
897	// through, the revision is not consumed and the rotation position survives.
898	func TestRegistryInvalidReplacementKeepsAcceptedStateAndCursor(t *testing.T) {
899		r := NewRegistry()
900		registerService(t, r, "svc", 0, []Instance{{ID: "a", Address: "h1:1"}, {ID: "b", Address: "h2:2"}})
901		markHealth(t, r, "svc", "a", 1, 11, true, "")
902		markHealth(t, r, "svc", "b", 1, 22, true, "")
903		// One successful selection lands the cursor on a.
904		if out := selected(t, r, "svc", 1); out.InstanceID != "a" || out.Address != "h1:1" || out.Sequence != 11 {
905			t.Fatalf("first select: %+v", out)
906		}
907	
908		// Valid prefix that would move a to a new address, invalid address later;
909		// expectedRevision 9 is also wrong but must not downgrade the answer to a
910		// conflict.
911		reg, err := r.ValidateRegistration("svc", 9, []Instance{
912			{ID: "a", Address: "h9:9"},
913			{ID: "b", Address: "bad-address"},
914		})
915		if err == nil {
916			t.Fatalf("expected an invalid-address error, got registration %+v", reg)
917		}
918		if msg := err.Error(); !strings.Contains(msg, `instance address "bad-address" is not a host:port address`) {
919			t.Fatalf("error should name the invalid address, got %q", msg)
920		}
921		if reg.Service != "" || reg.Revision != 0 || reg.Instances != nil {
922			t.Fatalf("failed validation must not return a partial registration: %+v", reg)
923		}
924	
925		// Nothing was applied: revision, original addresses, health and sequences
926		// are all the accepted ones; the rejected new address is absent.
927		assertAcceptedServiceState(t, r)
928	
929		// The cursor did not move: the rotation continues just after a and returns
930		// b's original address and accepted sequence instead of repeating a.
931		if out := selected(t, r, "svc", 1); out.InstanceID != "b" || out.Address != "h2:2" || out.Sequence != 22 || out.Revision != 1 {
932			t.Fatalf("select after invalid replacement should resume at b with its original state: %+v", out)
933		}
934		// Past the end the rotation wraps; the rejected new address must never be
935		// selectable even though it sat in the valid prefix.
936		if out := selected(t, r, "svc", 1); out.InstanceID != "a" || out.Address != "h1:1" || out.Sequence != 11 {
937			t.Fatalf("wrapped select should use a's original address, got %+v", out)
938		}
939	}
940	
941	// TestRegistryConflictReplacementKeepsAcceptedStateAndCursor covers the
942	// conflict rejection condition: a fully valid replacement list that changes an
943	// existing address but carries an expectedRevision other than the current one
944	// is reported as conflict with both revisions and changes nothing — no revision
945	// bump, no address change, no health reset, no cursor movement.
946	func TestRegistryConflictReplacementKeepsAcceptedStateAndCursor(t *testing.T) {
947		r := NewRegistry()
948		registerService(t, r, "svc", 0, []Instance{{ID: "a", Address: "h1:1"}, {ID: "b", Address: "h2:2"}})
949		markHealth(t, r, "svc", "a", 1, 11, true, "")
950		markHealth(t, r, "svc", "b", 1, 22, true, "")
951		if out := selected(t, r, "svc", 1); out.InstanceID != "a" || out.Address != "h1:1" || out.Sequence != 11 {
952			t.Fatalf("first select: %+v", out)
953		}
954	
955		// Entire list parses; only expectedRevision 5 mismatches the current 1.
956		reg, err := r.ValidateRegistration("svc", 5, []Instance{
957			{ID: "a", Address: "hx:8080"},
958			{ID: "b", Address: "h2:2"},
959		})
960		if err != nil {
961			t.Fatalf("content should be valid, got %v", err)
962		}
963		out := r.Apply(reg)
964		if out.OK || out.Kind != OutcomeConflict || out.Changed ||
965			out.Expected != 5 || out.Actual != 1 || out.Revision != 1 {
966			t.Fatalf("replacement should conflict without changing state: %+v", out)
967		}
968		if msg := out.Reason; !strings.Contains(msg, "revision 1, not 5") {
969			t.Fatalf("conflict reason should state both revisions, got %q", msg)
970		}
971	
972		// The valid-but-conflicting replacement left no trace: a is still at its
973		// original address, healthy at the accepted sequence 11.
974		assertAcceptedServiceState(t, r)
975	
976		// The completed selection's position is untouched: the next healthy target
977		// in rotation is b, then the wrap returns a's original address — never the
978		// rejected hx:8080 and never a repeated a.
979		if out := selected(t, r, "svc", 1); out.InstanceID != "b" || out.Address != "h2:2" || out.Sequence != 22 || out.Revision != 1 {
980			t.Fatalf("select after conflict should resume at b with its original state: %+v", out)
981		}
982		if out := selected(t, r, "svc", 1); out.InstanceID != "a" || out.Address != "h1:1" || out.Sequence != 11 || out.Revision != 1 {
983			t.Fatalf("wrapped select should use a's original address, got %+v", out)
984		}
985	}
