1	// Command indexroom is the 链上索引与交易分析服务 entry point.
2	package main
3	
4	import (
5		"encoding/json"
6		"fmt"
7		"io"
8		"os"
9		"strings"
10	
11		"github.com/gzhysuiioo/indexroom-analytics/indexroom"
12	)
13	
14	func main() {
15		command := "demo"
16		if len(os.Args) > 1 {
17			command = os.Args[1]
18		}
19		switch command {
20		case "demo":
21			runDemo()
22		case "version":
23			fmt.Println("indexroom 0.1.0")
24		case "register":
25			os.Exit(runRegister())
26		case "help", "-h", "--help":
27			usage()
28		default:
29			fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
30			usage()
31			os.Exit(2)
32		}
33	}
34	
35	func usage() {
36		fmt.Println("usage: indexroom [demo|version|register|help]")
37		fmt.Println()
38		fmt.Println("register reads requests as JSON from standard input and maintains an")
39		fmt.Println("in-memory service instance registry with offline health observations:")
40		fmt.Println(`  {"requests":[{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"i1","address":"host:8080"}]},`)
41		fmt.Println(`              {"type":"health","service":"svc","instanceId":"i1","expectedRevision":1,"sequence":1,"healthy":true},`)
42		fmt.Println(`              {"type":"select","service":"svc","expectedRevision":1}]}`)
43		fmt.Println("A register request fully replaces the service's instance list; new services")
44		fmt.Println("require expectedRevision 0, existing services the current revision. A health")
45		fmt.Println("request records an offline observation (healthy/unhealthy) for one instance;")
46		fmt.Println("it never probes. Health updates never bump the registration revision. A")
47		fmt.Println("select request chooses one healthy instance, rotating per service by ascending")
48		fmt.Println("instance id; it performs no network access and never changes revisions or")
49		fmt.Println("health records, and reports invalid/conflict/not_found/no_healthy on failure.")
50		fmt.Println("Exit status is 0 only when every request succeeds.")
51	}
52	
53	// registerInstance is one instance in the final service list.
54	type registerInstance struct {
55		ID       string `json:"id"`
56		Address  string `json:"address"`
57		Health   string `json:"health"`
58		Sequence int64  `json:"sequence"`
59		Reason   string `json:"reason,omitempty"`
60	}
61	
62	// registerService is one service in the final service list.
63	type registerService struct {
64		Service   string             `json:"service"`
65		Revision  int                `json:"revision"`
66		Instances []registerInstance `json:"instances"`
67	}
68	
69	// registerResult is the per-item outcome.
70	type registerResult struct {
71		Service          string `json:"service"`
72		OK               bool   `json:"ok"`
73		Changed          bool   `json:"changed,omitempty"`
74		Revision         int    `json:"revision"`
75		Error            string `json:"error,omitempty"`
76		Reason           string `json:"reason,omitempty"`
77		ExpectedRevision int    `json:"expectedRevision,omitempty"`
78		ActualRevision   int    `json:"actualRevision,omitempty"`
79		Sequence         int64  `json:"sequence,omitempty"`
80		InstanceID       string `json:"instanceId,omitempty"`
81		Address          string `json:"address,omitempty"`
82	}
83	
84	// registerOutput is the full register output.
85	type registerOutput struct {
86		Results  []registerResult  `json:"results"`
87		Services []registerService `json:"services"`
88	}
89	
90	// runRegister processes registration requests from standard input.
91	// It returns the process exit code: 0 when all registrations succeed, 1 otherwise.
92	func runRegister() int {
93		data, err := io.ReadAll(os.Stdin)
94		if err != nil {
95			return failRegister(fmt.Sprintf("could not read standard input: %v", err))
96		}
97	
98		var top struct {
99			Requests json.RawMessage `json:"requests"`
100		}
101		if err := json.Unmarshal(data, &top); err != nil {
102			return failRegister(fmt.Sprintf("input must be a JSON object with a requests array: %v", err))
103		}
104		if len(top.Requests) == 0 || strings.TrimSpace(string(top.Requests)) == "null" {
105			return failRegister("input must contain a \"requests\" array")
106		}
107		var rawRequests []json.RawMessage
108		if err := json.Unmarshal(top.Requests, &rawRequests); err != nil {
109			return failRegister("\"requests\" must be a JSON array")
110		}
111	
112		proc := &registerProcessor{
113			registry: indexroom.NewRegistry(),
114			results:  make([]registerResult, 0, len(rawRequests)),
115		}
116	
117		for _, raw := range rawRequests {
118			var head struct {
119				Service string          `json:"service"`
120				Type    json.RawMessage `json:"type"`
121			}
122			_ = json.Unmarshal(raw, &head)
123			service := strings.TrimSpace(head.Service)
124	
125			reqType := "register"
126			if len(head.Type) > 0 && strings.TrimSpace(string(head.Type)) != "null" {
127				var t string
128				if err := json.Unmarshal(head.Type, &t); err != nil {
129					proc.invalid(service, "type must be a string")
130					continue
131				}
132				reqType = t
133			}
134	
135			switch reqType {
136			case "", "register":
137				proc.registerRequest(raw, service)
138			case "health":
139				proc.healthRequest(raw, service)
140			case "select":
141				proc.selectRequest(raw, service)
142			default:
143				proc.invalidf(service, "unknown type %q", reqType)
144			}
145		}
146	
147		results, anyFailed := proc.results, proc.failed
148		registry := proc.registry
149	
150		services := make([]registerService, 0)
151		for _, view := range registry.Snapshot() {
152			insts := make([]registerInstance, 0, len(view.Instances))
153			for _, inst := range view.Instances {
154				insts = append(insts, registerInstance{
155					ID:       inst.ID,
156					Address:  inst.Address,
157					Health:   string(inst.Health),
158					Sequence: inst.Sequence,
159					Reason:   inst.Reason,
160				})
161			}
162			services = append(services, registerService{
163				Service:   view.Service,
164				Revision:  view.Revision,
165				Instances: insts,
166			})
167		}
168	
169		writeRegisterOutput(registerOutput{Results: results, Services: services})
170		if anyFailed {
171			return 1
172		}
173		return 0
174	}
