238			return
239		}
240		service = strings.TrimSpace(req.Service)
241	
242		if req.Revision == nil {
243			p.invalid(service, "expectedRevision is required and must be a non-negative integer")
244			return
245		}
246		if !isJSONArray(req.Instances) {
247			p.invalid(service, "instances must be an array")
248			return
249		}
250		var instances []indexroom.Instance
251		if err := json.Unmarshal(req.Instances, &instances); err != nil {
252			p.invalidf(service, "instances must be an array of objects with id and address: %v", err)
253			return
254		}
255	
256		registration, err := p.registry.ValidateRegistration(service, int(*req.Revision), instances)
257		if err != nil {
258			p.invalid(service, err.Error())
259			return
260		}
261	
262		outcome := p.registry.Apply(registration)
263		if !outcome.OK {
264			p.reject(outcome.Service, outcome.Kind, outcome.Reason, outcome.Revision, outcome.Expected, outcome.Actual, 0)
265			return
