274	// healthRequest processes one health observation request, appending its outcome.
275	func (p *registerProcessor) healthRequest(raw json.RawMessage, service string) {
276		var req struct {
277			Service    string  `json:"service"`
278			InstanceID string  `json:"instanceId"`
279			Revision   *int64  `json:"expectedRevision"`
280			Sequence   *int64  `json:"sequence"`
281			Healthy    *bool   `json:"healthy"`
