348			return
349		}
350	
351		outcome := p.registry.Select(selection)
352		if !outcome.OK {
353			p.reject(outcome.Service, outcome.Kind, outcome.Reason, outcome.Revision, outcome.Expected, outcome.Actual, 0)
354			return
355		}
356		p.succeed(registerResult{
357			Service:    outcome.Service,
358			Revision:   outcome.Revision,
